class Solution:
    def areAnagrams(self, root1, root2):
        from collections import deque, Counter

        def level_order_traversal(root):
            if not root:
                return []
            result = []
            queue = deque([root])
            while queue:
                level_size = len(queue)
                level_nodes = []
                for _ in range(level_size):
                    node = queue.popleft()
                    level_nodes.append(node.data)
                    if node.left:
                        queue.append(node.left)
                    if node.right:
                        queue.append(node.right)
                result.append(Counter(level_nodes))
            return result

        level_counts1 = level_order_traversal(root1)
        level_counts2 = level_order_traversal(root2)

        return 1 if level_counts1 == level_counts2 else 0
